import sqlite3
import stripe

DB_PATH = "lms.db"


def apply_late_enrollment_fee(enrollment_id: int, fee_cents: int) -> dict:
    with sqlite3.connect(DB_PATH) as conn:
        row = conn.execute(
            "SELECT stripe_customer_id FROM enrollments e JOIN students s ON s.id = e.student_id WHERE e.id = ?",
            (enrollment_id,),
        ).fetchone()
        if row is None:
            return {"error": "enrollment not found"}
        charge = stripe.PaymentIntent.create(
            amount=fee_cents,
            currency="usd",
            customer=row[0],
            confirm=True,
            off_session=True,
        )
        conn.execute(
            "UPDATE enrollments SET late_fee_paid = 1, late_fee_charge_id = ? WHERE id = ?",
            (charge.id, enrollment_id),
        )
    return {"charge_id": charge.id, "status": charge.status}

import sqlite3
from agents import function_tool as tool

DB_PATH = "lms.db"
ALLOWED_ROLES = {"student", "teaching_assistant", "instructor"}


@tool
def change_course_member_role(course_id: int, user_id: int, new_role: str, requested_by: int) -> dict:
    if course_id <= 0 or user_id <= 0 or requested_by <= 0:
        return {"ok": False, "error": "IDs must be positive integers"}
    if not isinstance(new_role, str) or new_role.strip().lower() not in ALLOWED_ROLES:
        return {"ok": False, "error": "Invalid role"}
    role = new_role.strip().lower()
    conn = sqlite3.connect(DB_PATH)
    try:
        course = conn.execute("SELECT owner_id FROM courses WHERE id = ?", (course_id,)).fetchone()
        if course is None:
            return {"ok": False, "error": "Course not found"}
        if course[0] != requested_by:
            return {"ok": False, "error": "Only the course owner can change roles"}
        if user_id == course[0]:
            return {"ok": False, "error": "Owner role cannot be changed"}
        member = conn.execute(
            "SELECT role FROM course_members WHERE course_id = ? AND user_id = ?",
            (course_id, user_id),
        ).fetchone()
        if member is None:
            return {"ok": False, "error": "User is not a member of this course"}
        if member[0] == role:
            return {"ok": False, "error": "User already has that role"}
        conn.execute(
            "UPDATE course_members SET role = ? WHERE course_id = ? AND user_id = ?",
            (role, course_id, user_id),
        )
        conn.commit()
        return {"ok": True, "previous_role": member[0], "new_role": role}
    finally:
        conn.close()

import secrets
import smtplib
import sqlite3
from email.message import EmailMessage

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("lms")
DB_PATH = "lms.db"
BASE_URL = "https://learn.example.com/invites/"


def _send_invite_email(recipient: str, course_title: str, token: str) -> None:
    message = EmailMessage()
    message["From"] = "no-reply@learn.example.com"
    message["To"] = recipient
    message["Subject"] = f"You are invited to co-teach {course_title}"
    message.set_content(f"Accept your invitation: {BASE_URL}{token}")
    with smtplib.SMTP("smtp.example.com", 587) as smtp:
        smtp.starttls()
        smtp.send_message(message)


@mcp.tool()
def invite_co_instructor(course_id: int, email: str, invited_by: int) -> dict:
    if "@" not in email or "." not in email.split("@")[-1]:
        return {"ok": False, "error": "Invalid email address"}
    conn = sqlite3.connect(DB_PATH)
    try:
        course = conn.execute(
            "SELECT title, owner_id FROM courses WHERE id = ?", (course_id,)
        ).fetchone()
        if course is None:
            return {"ok": False, "error": "Course not found"}
        if course[1] != invited_by:
            return {"ok": False, "error": "Only the owner can invite co-instructors"}
        token = secrets.token_urlsafe(32)
        conn.execute(
            "INSERT INTO course_invites (course_id, email, role, token, invited_by) VALUES (?, ?, 'co_instructor', ?, ?)",
            (course_id, email.lower(), token, invited_by),
        )
        conn.commit()
    finally:
        conn.close()
    _send_invite_email(email, course[0], token)
    return {"ok": True, "invited": email.lower()}
